// ─── Constants ─────────────────────────────────────────────

const LOG_WARNINGS = true;   // set false to suppress console warnings

function warn(message) {
  if (LOG_WARNINGS) console.warn('[FogParser]', message);
}

// ─── determineDeviceType ───────────────────────────────────

function determineDeviceType(systype) {
  if (!systype) return 'OTHER';
  const t = systype.toUpperCase();
  if (t.includes('ALL IN ONE') || t.includes('ALL-IN-ONE')) return 'ALL_IN_ONE';
  if (t.includes('NOTEBOOK') || t.includes('LAPTOP'))           return 'LAPTOP';
  if (t.includes('DESKTOP') || t.includes('TOWER'))             return 'DESKTOP';
  if (t.includes('TABLET'))                                      return 'TABLET';
  if (t.includes('SERVER'))                                      return 'SERVER';
  return 'OTHER';
}

// ─── determineStorageType ──────────────────────────────────

function determineStorageType(hdmodel) {
  if (!hdmodel || hdmodel === 'Unknown') return 'UNKNOWN';

  const m = hdmodel.toUpperCase().trim();

  // ── Explicit type indicators (highest confidence) ──
  if (m.includes('NVME'))                        return 'NVME';
  if (m.includes('EMMC'))                        return 'EMMC';
  if (m.includes('SSD') || m.includes('SOLID'))  return 'SSD';
  if (m.includes('MSATA'))                       return 'SSD';

  // ── WD SSD (WDS prefix) — must come before WD HDD check ──
  if (/^WDS\d{3,4}G/i.test(m))                  return 'SSD';

  // ── Known HDD manufacturer patterns ──
  // WD HDDs: WD10EZEX, WD5000AAKS, WD1600AAJS
  if (/^WDC?\s*WD\d{2,4}[A-Z]/i.test(m) || /^WD\d{2,4}[A-Z]/i.test(m)) return 'HDD';
  // Seagate: ST1000DM003
  if (/^ST\d{3,4}/i.test(m))                    return 'HDD';
  // Toshiba HDD: DT01ACA100, MQ01ABD100, HDWD130
  if (/TOSHIBA.*(?:DT\d|MQ\d|HDW\d|MD\d)/i.test(m)) return 'HDD';
  // HGST/Hitachi
  if (/HGST|HITACHI|H[UT]S\d/i.test(m))         return 'HDD';

  // ── Known SSD manufacturer/brand patterns (no "SSD" in name) ──
  if (/KIOXIA|KBG\d|KXG\d/i.test(m))            return 'SSD';
  if (/(?:SK\s*HYNIX|BC\d{3}|HFM\d|HFS\d)/i.test(m)) return 'SSD';
  if (/SAMSUNG.*(?:PM\d|SM\d|MZ|EVO|PRO|QVO)/i.test(m)) return 'SSD';
  if (/MICRON|CRUCIAL|MTFD/i.test(m))            return 'SSD';
  if (/INTEL.*(?:SSD|OPTANE)/i.test(m) || /SSDPE|SSDSC/i.test(m)) return 'SSD';
  if (/KINGSTON/i.test(m))                       return 'SSD';
  if (/LITEON|LITE-ON/i.test(m))                 return 'SSD';
  if (/SANDISK/i.test(m))                        return 'SSD';
  if (/PNY/i.test(m))                            return 'SSD';
  if (/CORSAIR|FORCE\s*MP/i.test(m))             return 'SSD';
  if (/ADATA/i.test(m))                          return 'SSD';
  if (/TEAM\s*(?:GROUP)?\s*(?:TM|T-)/i.test(m))  return 'SSD';
  if (/PATRIOT/i.test(m))                        return 'SSD';

  warn(`Storage type UNKNOWN for hdmodel: "${hdmodel}"`);
  return 'UNKNOWN';
}

// ─── determineStorageSize ──────────────────────────────────

function determineStorageSize(hdmodel) {
  if (!hdmodel || hdmodel === 'Unknown') return 0;

  let match;

  // ── Explicit "XXXGB" or "XXX GB" ──
  match = hdmodel.match(/(\d+)\s*GB/i);
  if (match) return parseInt(match[1], 10);

  // ── Explicit "X.XTB" or "X TB" → convert to GB ──
  match = hdmodel.match(/(\d+(?:\.\d+)?)\s*TB/i);
  if (match) return Math.round(parseFloat(match[1]) * 1000);

  // ── WD Blue/Green/Black SSD: "WDS500G2B0A" → 500 ──
  match = hdmodel.match(/WDS(\d{3,4})G/i);
  if (match) return parseInt(match[1], 10);

  // ── Inline capacity: "256G", "512G" (above 32 avoids cache/ram false matches) ──
  match = hdmodel.match(/(\d{3,4})G\b/i);
  if (match) {
    const val = parseInt(match[1], 10);
    if (val > 32) return val;
  }

  // ── Western Digital HDD capacity codes ──
  //   WD10 = 1.0TB, WD20 = 2.0TB   (2-digit: ×100 GB)
  //   WD5000 = 500GB, WD1600 = 160GB (4-digit: ÷10 GB)
  //   WD500 = 500GB                  (3-digit: as-is GB)
  match = hdmodel.match(/\bWD(\d{2,4})(?![0-9])/i);
  if (match) {
    const wdCode = parseInt(match[1], 10);
    if (wdCode >= 10 && wdCode <= 200)      return wdCode * 100;
    if (wdCode >= 1000 && wdCode <= 16000)  return Math.round(wdCode / 10);
    if (wdCode >= 320 && wdCode <= 999)     return wdCode;
  }

  // ── Toshiba HDD: DT01ACA100 → 1000, MQ01ABD100 → 1000 ──
  match = hdmodel.match(/(?:DT01ACA|MQ01AB[DF])(\d{3})/i);
  if (match) return parseInt(match[1], 10) * 10;

  // ── Seagate HDD: ST1000 → 1000, ST250 → 250 ──
  match = hdmodel.match(/\bST(\d{3,4})(?![0-9])/i);
  if (match) {
    const stVal = parseInt(match[1], 10);
    if (stVal >= 250) return stVal;
  }

  warn(`Storage size UNKNOWN for hdmodel: "${hdmodel}"`);
  return 0;
}

// ─── parseHost (single host → single output item) ──────────

function parseHost(hostObj, inventoryObj) {
  try {
    const inv = inventoryObj || {};
    if (!inv.sysserial && !inv.sysman && !inv.cpuversion) {
      warn(`Host "${hostObj.name}" has empty or missing inventory — specs will be sparse`);
    }

    const manufacturer = inv.sysman || 'Unknown';

    // Lenovo puts the meaningful model in sysversion; others use sysproduct
    let model_name;
    if (manufacturer.toUpperCase().includes('LENOVO')) {
      model_name = inv.sysversion || inv.sysproduct || 'Unknown';
    } else {
      model_name = inv.sysproduct || inv.sysversion || 'Unknown';
    }

    const hdmodel = inv.hdmodel || '';

    return {
      json: {
        serial_number:   inv.sysserial || hostObj.name,
        manufacturer:    manufacturer,
        model_name:      model_name,
        processor:       inv.cpuversion || 'Unknown',
        gpu: `${inv.gpuvendors || ''} ${inv.gpuproducts || ''}`.trim(),
        memory_gb:       Math.round(parseFloat((inv.memory || '0 GiB').replace(' GiB', '')) || 0),
        storage_type:    determineStorageType(hdmodel),
        storage_size_gb: determineStorageSize(hdmodel),
        hdmodel_raw:     hdmodel,
        hdmodel_raw:     hdmodel,
        drive_serial:    inv.hdserial || '',
        drive_serial:    inv.hdserial || '',
        mac_address:     hostObj.primac || '',
        device_type:     determineDeviceType(inv.systype),
        host_name:       hostObj.name
      }
    };

  } catch (err) {
    const inv = inventoryObj || {};
    warn(`Parse error for host "${hostObj.name}": ${err.message}`);
    return {
      json: {
        serial_number:   inv.sysserial || hostObj.name || 'ERROR',
        manufacturer:    'Unknown',
        model_name:      'Unknown',
        processor:       'Unknown',
        gpu: `${inv.gpuvendors || ''} ${inv.gpuproducts || ''}`.trim(),
        memory_gb:       0,
        storage_type:    'UNKNOWN',
        storage_size_gb: 0,
        mac_address:     hostObj.primac || '',
        device_type:     'OTHER',
        host_name:       hostObj.name || 'ERROR',
        _parse_error:    err.message
      }
    };
  }
}

// ─── Main ──────────────────────────────────────────────────

// Single host from orchestrator (has inventory as a direct property)
if ($json.inventory) {
  return [parseHost($json, $json.inventory)];
}

// Batch from test data with data.hosts array
const hosts = $json?.data?.hosts || [];
if (!hosts.length) {
  warn('No hosts found in input — returning empty');
  return [];
}

return hosts.map(h => parseHost(h, h.inventory || {}));
